update public.cms_sections set data='{"eyebrow": "Certifications & awards", "heading": "Safety Recognised by Our Clients", "awards": [{"heading": "ISO 9001", "description": "Operations follow ISO 9001 certification standards. [Confirm certificate holder and year]", "image": "/hsse/award-1.png", "imagePlaceholder": "[Award image 1]"}, {"heading": "BP Pakistan E&P", "description": "Recognised for safety performance (2001).", "image": "/hsse/award-2.png", "imagePlaceholder": "[Award image 2]"}, {"heading": "Road safety award", "description": "Awarded for road safety participation. [Add year and awarding body]", "image": "/hsse/award-3.png", "imagePlaceholder": "[Award image 3]"}], "policy": {"heading": "Download Our HSSE Policy", "description": "Read the policy that guides how we run drivers, vehicles, cargo and operations.", "metadata": "[LMI-HSSE-Policy.pdf · file size · year/version]", "label": "Download PDF", "path": null, "badge": "PDF"}, "action": {"label": "See all certifications & recognitions", "path": "/company/certifications-recognitions"}}'::jsonb,revision=70 where page_id='hsse' and key='sectionEight';
update public.cms_sections set data='{"eyebrow": "Before dispatch", "heading": "Vehicle Readiness & Maintenance", "image": "/hsse/section-4-main-image.png", "imageAlt": "Vehicle inspection in progress", "imagePlaceholder": "[Photo: vehicle inspection in progress]", "items": ["Planned vehicle inspections", "Preventive maintenance", "Pre-dispatch readiness checks", "Fire-safety and protective equipment on board", "Tyres, brakes and mechanical condition"]}'::jsonb,revision=70 where page_id='hsse' and key='sectionFour';
update public.cms_sections set data='{"eyebrow": "Our commitment", "heading": "HSSE & Road Transport Safety in Pakistan", "description": "A clear HSSE policy guides how LMI plans every journey, covering our drivers, vehicles, cargo and operations, from the first check to the final delivery.", "action": {"label": "Discuss Your Requirement", "path": "/contact-us"}, "image": "/hsse/section-1-main-image.png", "imageAlt": "LMI driver beside a tanker", "imagePlaceholder": "[Photo: LMI driver beside a tanker]"}'::jsonb,revision=70 where page_id='hsse' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "People first", "heading": "Employee Support After Incidents", "description": "Our drivers and staff work in demanding conditions, and LMI stands behind them. If an incident happens, support for the people involved starts immediately and does not depend on whose fault it was.", "items": ["Medical support: prompt access to medical care and follow-up for the employee involved", "Financial assistance: help with costs while the employee recovers or the situation is resolved", "Legal assistance: guidance and support through any formal or legal process that follows"], "image": "/hsse/section-7-main-image.png", "imageAlt": "LMI team with safety supervisors", "imagePlaceholder": "[Photo: LMI team with safety supervisors]"}'::jsonb,revision=70 where page_id='hsse' and key='sectionSeven';
